19	    .job-status { font-weight: 600; }
20	    .job-result { overflow-wrap: anywhere; }
21	  </style>
22	</head>
23	<body>
24	  <h1>Job tracker</h1>
25	
26	  <form data-testid="job-form" id="job-form" novalidate>
27	    <label>Input
28	      <input data-testid="job-input" name="input" type="text" autocomplete="off">
29	    </label>
30	    <label>Steps
31	      <input data-testid="job-steps" name="steps" type="text" inputmode="numeric" value="5">
32	    </label>
33	    <label>Fail attempts
34	      <input data-testid="job-fail-attempts" name="failAttempts" type="text" inputmode="numeric" value="0">
35	    </label>
36	    <button data-testid="job-submit" type="submit">Submit job</button>
37	  </form>
38	
39	  <div data-testid="form-error" role="alert" id="form-error"></div>
40	
41	  <ul data-testid="job-list" id="job-list"></ul>
42	
43	  <script>
44	    const form = document.getElementById('job-form');
45	    const errorBox = document.getElementById('form-error');
46	    const list = document.getElementById('job-list');
47	
48	    // Numeric values are sent as numbers so that the API applies its own validation. Anything that
49	    // is not a number is sent as typed, and the API rejects it naming the field.
50	    function fieldValue(raw) {
51	      const text = raw.trim();
52	      const n = Number(text);
53	      return text !== '' && Number.isFinite(n) ? n : raw;
54	    }
55	
56	    function showError(message, fields) {
57	      errorBox.replaceChildren();
58	      if (!message && !(fields && fields.length)) return;
59	      const p = document.createElement('p');
60	      p.textContent = message;
61	      errorBox.append(p);
62	      if (fields && fields.length) {
63	        const ul = document.createElement('ul');
64	        for (const f of fields) {
65	          const li = document.createElement('li');
66	          li.textContent = `${f.field}: ${f.message}`;
67	          ul.append(li);
68	        }
69	        errorBox.append(ul);
70	      }
71	    }
72	
73	    form.addEventListener('submit', async (event) => {
74	      event.preventDefault();
75	      const data = new FormData(form);
76	      // The input text is sent exactly as typed; only the numeric fields are converted.
77	      const body = {
78	        input: String(data.get('input') ?? ''),
79	        steps: fieldValue(String(data.get('steps') ?? '')),
80	        failAttempts: fieldValue(String(data.get('failAttempts') ?? '')),
81	      };
82	      const button = form.querySelector('[data-testid="job-submit"]');
83	      button.disabled = true;
84	      try {
85	        const res = await fetch('/api/jobs', {
86	          method: 'POST',
87	          headers: { 'content-type': 'application/json' },
88	          body: JSON.stringify(body),
89	        });
90	        const json = await res.json().catch(() => null);
91	        if (res.ok) {
92	          showError('', []);
93	          form.querySelector('[name="input"]').value = '';
94	          await refresh();
95	        } else {
96	          const err = json && json.error ? json.error : {};
97	          showError(err.message || `Request failed with status ${res.status}.`, err.fields || []);
98	        }
99	      } catch (e) {
100	        showError(`Could not reach the server: ${e.message}`, []);
101	      } finally {
102	        button.disabled = false;
103	      }
104	    });
105	
106	    function jobItem(job) {
107	      const li = document.createElement('li');
108	      li.dataset.testid = 'job-item';
109	      li.dataset.jobId = job.id;
110	
111	      const input = document.createElement('span');
112	      input.className = 'job-input';
113	      input.textContent = job.input;
114	
115	      const status = document.createElement('span');
116	      status.dataset.testid = 'job-status';
117	      status.className = 'job-status';
118	      status.textContent = job.status;
119	
120	      const progress = document.createElement('span');
121	      progress.dataset.testid = 'job-progress';
122	      progress.textContent = `${job.progress.completed}/${job.progress.total}`;
123	
124	      const result = document.createElement('span');
125	      result.dataset.testid = 'job-result';
126	      result.className = 'job-result';
127	      if (job.status === 'completed') result.textContent = job.result ? job.result.output : '';
128	      else if (job.status === 'failed') result.textContent = job.error || '';
129	      else result.textContent = '';
130	
131	      li.append(input, status, progress, result);
132	      return li;
133	    }
134	
135	    async function refresh() {
136	      try {
137	        const res = await fetch('/api/jobs');
138	        if (!res.ok) return;
139	        const { jobs } = await res.json();
140	        list.replaceChildren(...jobs.map(jobItem));
141	      } catch {
142	        // Keep the last list on screen; the next poll retries.
143	      }
144	    }
